const PATHS=[['words','◫','الكلمات والأفعال','افهم الكلمة، واسمعها، واستخدمها في سياق.'],['build','⌘','بناء الجمل والأسئلة','من كلمة لجملة… ومن جملة لسؤال.'],['speak','♬','النطق والمحادثة','اسمع، كرّر، وردّ بطريقتك الطبيعية.'],['grammar','✎','القواعد ببساطة','قاعدة واضحة، ومثال، وتطبيق عملي.'],['write','▤','الكتابة والتصحيح','اكتب إجابتك وافهم إزاي تحسّنها.'],['quiz','✓','اختبر نفسك','أسئلة قصيرة عشوائية تثبّت اللي اتعلّمته.']];

const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={level:'A1',records:[],items:{},visits:[],lastWeekly:null}, storageOK=true;
try{const v=JSON.parse(localStorage.getItem('schritt-v1'));if(v&&Array.isArray(v.records)&&v.items&&Array.isArray(v.visits))state={...state,...v};}catch{storageOK=false;}
let view='home', mode='words', topic=null, quiz=null, step=0, flipped=false, audioURL=null, recorder=null, stream=null, countdown=null;
const statusLabels=['جديد','قيد التدريب','يحتاج مراجعة','متقن'];
const icons={home:'<path d="m3 10 9-7 9 7v10H3zM9 20v-7h6v7"/>',paths:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',speak:'<rect x="8" y="2" width="8" height="13" rx="4"/><path d="M4 10v2a8 8 0 0 0 16 0v-2M12 20v3M8 23h8"/>',review:'<path d="M4 9a9 9 0 1 1 0 7M4 3v6h6M12 7v6l4 2"/>',quiz:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V2h6v2M9 11l2 2 4-4M9 17h6"/>',progress:'<path d="M4 20V9M10 20V4M16 20v-8M22 20H1"/>'};
const navs=[['home','لوحة التعلّم'],['paths','مسارات التعلّم'],['speak','النطق والمحادثة'],['review','المراجعة الذكية'],['quiz','اختبر نفسك'],['progress','تقدّمي وأخطائي']];
function save(){try{localStorage.setItem('schritt-v1',JSON.stringify(state));}catch{storageOK=false;}updateHeader();}
function updateHeader(){const e=$('.header-actions');if(e)e.innerHTML=`<span class="local-dot"></span>${storageOK?'تقدّمك محفوظ على هذا المتصفح':'تعذّر الحفظ؛ التقدّم مؤقت في هذه الجلسة'} <button id="help" aria-label="معلومات الحفظ">ⓘ</button>`;$('#help').onclick=()=>showModal('<h3>مساحتك الخاصة</h3><p>التقدّم محفوظ محليًا على هذا المتصفح، ولا يتزامن بين الأجهزة. مسح بيانات المتصفح قد يحذف السجل. يمكنك تنزيل نسخة احتياطية واستعادتها من صفحة تقدّمي.</p><p>لا ينفذ المدرب أي إجراءات خارجية. التسجيل الصوتي محلي ولا يُرفع. الأصوات المتاحة تعتمد على جهازك؛ نستخدم صوتًا ألمانيًا محليًا إن توفر.</p>');}
function getItem(id){return state.items[id]||{status:0,ok:0,bad:0,last:null,next:null};}
function record(t,correct,kind,detail=''){const it={...getItem(t.id)};it.ok+=correct?1:0;it.bad+=correct?0:1;it.status=correct?(it.ok>=3&&it.ok>it.bad+1?3:1):2;it.last=Date.now();it.next=Date.now()+(correct?(it.status===3?7:1):0)*86400000;state.items[t.id]=it;state.records.unshift({id:t.id,correct,kind,detail,time:Date.now()});state.records=state.records.slice(0,1200);const day=new Date().toLocaleDateString('en-CA');if(!state.visits.includes(day))state.visits.push(day);save();}
function manualStatus(id,n){const it={...getItem(id),status:+n,last:Date.now(),next:Date.now()+(+n===3?7:+n===1?1:0)*86400000};state.items[id]=it;save();}
function filtered(){return TOPICS.filter(t=>t.level===state.level);}
function due(){return TOPICS.filter(t=>{const i=getItem(t.id);return i.status===2||(i.last&&i.next<=Date.now());});}
function levelTabs(){return `<div class="levels" aria-label="المستوى">${['A1','A2','B1','B2'].map(l=>`<button data-level="${l}" class="${state.level===l?'active':''}">${l}</button>`).join('')}</div>`;}
function go(v){stopMedia();view=v;topic=null;quiz=null;render();window.scrollTo(0,0);}
function render(){ $('#nav').innerHTML=navs.map(([v,l])=>`<a href="#${v}" data-nav="${v}" class="${v===view?'active':''}"><svg viewBox="0 0 24 24">${icons[v]}</svg>${l}${v==='review'&&due().length?`<em>${due().length}</em>`:''}</a>`).join('');$('#page-name').textContent=(navs.find(n=>n[0]===view)||navs[0])[1]; if(topic)renderExercise();else if(quiz)renderQuiz();else ({home:home,paths:paths,speak:()=>catalog('speak'),review:review,quiz:quizLanding,progress:progress}[view]||home)();bind();updateHeader();}
function bind(){document.querySelectorAll('[data-nav]').forEach(e=>e.onclick=()=>go(e.dataset.nav));document.querySelectorAll('[data-level]').forEach(e=>e.onclick=()=>{state.level=e.dataset.level;save();render();});document.querySelectorAll('[data-mode]').forEach(e=>e.onclick=()=>{mode=e.dataset.mode;view='paths';topic=null;render();});document.querySelectorAll('[data-topic]').forEach(e=>e.onclick=()=>openTopic(e.dataset.topic,e.dataset.kind||mode));document.querySelectorAll('[data-quiz]').forEach(e=>e.onclick=()=>startQuiz(e.dataset.quiz));document.querySelectorAll('[data-say]').forEach(e=>e.onclick=()=>say(e.dataset.say));document.querySelectorAll('[data-status]').forEach(e=>e.onchange=()=>manualStatus(e.dataset.status,e.value));}
function pathCards(){return PATHS.map(([m,ic,title,desc])=>{const count=filtered().filter(t=>getItem(t.id).status===3).length;return `<button class="path" data-mode="${m}"><span class="arrow">↖</span><span class="icon">${ic}</span><h3>${title}</h3><p>${desc}</p><div class="path-bottom"><span>${filtered().length} تدريب · ${state.level}</span><span>${count} متقن</span></div><div class="progress-line"><span style="width:${count/filtered().length*100}%"></span></div></button>`;}).join('');}
function home(){const practiced=TOPICS.filter(t=>getItem(t.id).last),mastered=TOPICS.filter(t=>getItem(t.id).status===3),accuracy=state.records.length?Math.round(state.records.filter(r=>r.correct).length/state.records.length*100):0; const next=filtered().find(t=>getItem(t.id).status!==3)||filtered()[0];$('#app').innerHTML=`<div class="intro"><div><div class="eyebrow">DEIN DEUTSCHER ALLTAG</div><h1>أهلًا بيك في خطوتك الجاية <span style="font-size:23px">🌿</span></h1><p>كل كلمة بتتعلمها، بتقرّبك من محادثة واثقة.</p></div><div class="datepill">▦ ${new Date().toLocaleDateString('ar-EG',{weekday:'long',day:'numeric',month:'long'})}</div></div><section class="hero"><div class="hero-copy"><span class="tag">✦ جلستك اليومية · ${state.level}</span><h2>الألماني بيتحسّن بالممارسة.<br><span>خلّينا ناخد خطوة النهارده.</span></h2><p>كلمة جديدة، جملة منك، ومحادثة صغيرة. ١٠ دقائق تعمل فرق.</p><button class="primary" data-topic="${next.id}" data-kind="daily">ابدأ جلسة اليوم <span>←</span></button><span class="tiny">◷ ١٠ دقائق على راحتك · اسمع، اكتب، واتكلم</span></div><div class="art" aria-hidden="true"><span class="spark">✧</span><div class="speech s1">Hallo!</div><div class="speech s2">Wie geht’s?</div></div></section><section class="stats">${[['✦','أيام الممارسة',state.visits.length,'يوم'],['◫','موضوعات اتدرّبت عليها',practiced.length,'موضوع'],['✓','دقّة الإجابات',accuracy,'%'],['↶','مستحق للمراجعة',due().length,'موضوع']].map(([i,l,n,u])=>`<div class="stat"><span class="stat-icon">${i}</span><div><small>${l}</small><strong>${n}</strong><span class="unit">${u}</span></div></div>`).join('')}</section><section><div class="section-title"><h2>اختار خطوتك النهارده</h2>${levelTabs()}</div><div class="split"><div class="paths">${pathCards()}</div><div class="review-card"><span class="overline">↶ وقت تثبيت اللي اتعلّمته</span><h3>التكرار… سرّ التقدّم.</h3><p>${due().length?`عندك ${due().length} موضوع محتاجين مراجعة خفيفة. نرجع لهم سوا؟`:'بعد أول تدريب، هتلاقي هنا الكلمات والموضوعات اللي محتاجة منك مراجعة.'}</p><div class="review-words">${(due().length?due():filtered()).slice(0,3).map(t=>`<span class="word-pill">${esc(t.word)}</span>`).join('')}</div><button class="secondary" onclick="go('review')">ابدأ المراجعة <span>←</span></button></div></div></section><div class="bottom-grid"><div class="panel"><div class="section-title"><h3>مواقف قريبة من يومك</h3><button class="text-link" onclick="go('paths')">كل الموضوعات ←</button></div>${filtered().slice(0,3).map((t,i)=>`<div class="topic-row"><span class="number">0${i+1}</span><div><b>${t.title}</b><small>${esc(t.question)}</small></div><button data-topic="${t.id}" data-kind="speak" aria-label="تدريب ${t.title}">←</button></div>`).join('')}</div><div class="panel"><div class="section-title"><h3>خطواتك هذا الأسبوع</h3><span class="badge">${mastered.length} موضوع متقن</span></div><div class="week-chart">${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const records=state.records.filter(r=>new Date(r.time).toDateString()===d.toDateString());return `<div class="bar-day"><div class="bar"><span style="height:${Math.min(records.length*12,100)}%" title="${records.length} محاولة"></span></div>${d.toLocaleDateString('ar-EG',{weekday:'short'})}</div>`;}).join('')}</div><div class="chart-note"><span>${state.records.length?'كل محاولة بتسيب أثر. كمّل على مهلك.':'أول جلسة ليك هتكون بداية الرسم هنا.'}</span><button class="text-link" onclick="go('progress')">تفاصيل التقدّم ←</button></div></div></div>`;}
function paths(){$('#app').innerHTML=`<div class="view-head"><h1>كل خطوة لها مسار</h1><p>اختار المهارة والمستوى، وابدأ من الموقف اللي يهمّك.</p></div><div class="toolbar">${levelTabs()}<select id="mode-select" aria-label="مسار التدريب">${PATHS.map(p=>`<option value="${p[0]}" ${p[0]===mode?'selected':''}>${p[2]}</option>`).join('')}</select></div><div id="catalog"></div>`;$('#mode-select').onchange=e=>{mode=e.target.value;render();};if(mode==='quiz'){$('#catalog').innerHTML=quizIntro();}else fillCatalog(filtered(),mode);}
function catalog(kind){$('#app').innerHTML=`<div class="view-head"><h1>صوتك… أوضح كل مرة</h1><p>اسمع النموذج، رد على السؤال، وسجّل صوتك للمقارنة الذاتية.</p></div><div class="toolbar">${levelTabs()}<span class="subtle">تدريب محلي · بدون رفع التسجيلات</span></div><div id="catalog"></div>`;fillCatalog(filtered(),kind);}
function fillCatalog(list,kind){$('#catalog').innerHTML=`<div class="lesson-grid">${list.map(t=>`<article class="panel"><div class="section-title"><span>${t.icon} ${t.level}</span><span class="badge">${statusLabels[getItem(t.id).status]}</span></div><h3>${t.title}</h3><div class="de">${esc(kind==='words'?t.word:kind==='grammar'?t.quiz:t.question)}</div><div class="subtle">${kind==='words'?t.meaning:'كلمة ← جملة ← سؤال ← رد طبيعي'}</div><button class="secondary" data-topic="${t.id}" data-kind="${kind}">ابدأ التدريب ←</button></article>`).join('')}</div>`;}
function openTopic(id,kind){stopMedia();topic=TOPICS.find(t=>t.id===id);if(!topic)return;mode=kind;step=0;flipped=false;quiz=null;render();window.scrollTo(0,0);}
function currentMode(){return mode==='daily'?['words','build','write','speak'][Math.min(step,3)]:mode;}
function renderExercise(){const t=topic,m=currentMode();$('#app').innerHTML=`<div class="view-head"><button class="text-link" onclick="go('paths')">→ الرجوع للمسارات</button></div><div class="exercise"><div class="panel"><div class="section-title"><span class="badge">${t.level} · ${t.title}</span><span class="subtle">${mode==='daily'?`جلسة اليوم · ${step+1} / 4`:PATHS.find(p=>p[0]===m)?.[2]||'تدريب'}</span></div><div id="exercise-body"></div><div id="exercise-feedback" aria-live="polite"></div><div class="actions" id="exercise-actions"></div></div></div>`;const body=$('#exercise-body');if(m==='words'){body.innerHTML=`<h2>من كلمة صغيرة… لمعنى تعرف تستخدمه</h2><div class="prompt de">${esc(t.word)} <button class="text-link" data-say="${esc(t.word)}" aria-label="اسمع الكلمة">◖))</button></div><p class="subtle">حاول تفتكر المعنى قبل ما تقلب البطاقة.</p><button class="secondary" id="flip">اكشف المعنى والمثال ↶</button><div id="card-back" hidden><h3>${t.meaning}</h3><p class="de">${esc(t.sentence)}</p><p class="subtle">${esc(t.translation)}</p><p class="writing-note">النموذج الأطول: <b class="inline-de">${esc(t.answer)}</b></p></div>`;$('#flip').onclick=()=>{$('#card-back').hidden=false;$('#flip').disabled=true;flipped=true;$('#exercise-actions').innerHTML=`<button class="primary" id="know">عرفتها ✓</button><button class="secondary" id="again">محتاج أراجعها</button>`;$('#know').onclick=()=>finishAttempt(true,'كلمات');$('#again').onclick=()=>finishAttempt(false,'كلمات',t.word);};}
else if(m==='build'){body.innerHTML=`<h2>حوّل الكلمة لجملة… وبعدين سؤال</h2><div class="steps"><span class="selected">١. كلمة</span><span>٢. جملة</span><span>٣. سؤال</span></div><div class="prompt de">${esc(t.word)}</div><label for="build-sentence">اكتب الجملة المرجعية من الكلمة (استخدم المساعدة عند الحاجة)</label><textarea id="build-sentence" placeholder="Schreib einen Satz …"></textarea><label for="build-question">اكتب السؤال المناسب لهذا الموقف</label><textarea id="build-question" placeholder="Stell eine Frage …"></textarea><button class="text-link" id="hint">عرض الهدف بالعربي ومساعدة</button><div class="subtle" id="hint-text"></div><p class="writing-note">التصحيح هنا يقارن بالنموذج المستهدف؛ جملة مختلفة صحيحة قد تحتاج مراجعة ذاتية.</p>`;$('#hint').onclick=()=>{$('#hint-text').innerHTML=`الجملة المستهدفة: <span class="inline-de">${esc(t.sentence)}</span><br>السؤال المستهدف: <span class="inline-de">${esc(t.question)}</span>`;};$('#exercise-actions').innerHTML='<button class="primary" id="check-build">راجع الجملة والسؤال ✓</button>';$('#check-build').onclick=()=>{const a=$('#build-sentence').value,b=$('#build-question').value;if(!a.trim()||!b.trim())return feedback(false,'اكتب الجملة والسؤال أولًا.');const ok=norm(a)===norm(t.sentence)&&norm(b)===norm(t.question);finishAttempt(ok,'جملة وسؤال',a+' | '+b,`<b>${ok?'ممتاز، الجملة والسؤال مطابقان للنموذج.':'قارن محاولتك بالنموذج المستهدف:'}</b><div class="de">${esc(t.sentence)}<br>${esc(t.question)}</div>${t.explain}<p>في السؤال الذي يبدأ بكلمة استفهام: كلمة السؤال، ثم الفعل، ثم الفاعل. في سؤال نعم/لا يبدأ الفعل أولًا.</p>`);};}
else if(m==='write'){body.innerHTML=`<h2>${t.write}</h2><p class="subtle">طبّق الفكرة بالألماني. بنراجع هنا إجابة محددة، مش أي نص حر.</p><textarea id="writing" placeholder="Deine Antwort …" aria-label="إجابتك بالألمانية" spellcheck="false"></textarea><p class="writing-note">نقبل الصيغ المرجعية الشائعة ونتجاهل علامات الترقيم وحالة الأحرف في المقارنة. الأسماء الألمانية تبدأ بحرف كبير.</p>`;$('#exercise-actions').innerHTML='<button class="primary" id="check-write">صحّح إجابتي ✓</button>';$('#check-write').onclick=()=>{const a=$('#writing').value;if(!a.trim())return feedback(false,'اكتب إجابتك الأول.');const ok=t.accepted.some(v=>norm(v)===norm(a));finishAttempt(ok,'كتابة',a,`<b>${ok?'إجابة صحيحة، خطوة حلوة!':'إجابتك لا تطابق الصيغ المرجعية لهذا التمرين.'}</b><div class="de">${esc(t.accepted[0])}</div><p>${t.writeExplain}</p>${!ok?'<small>لو استخدمت صياغة مختلفة صحيحة، قارنها بنفسك؛ هذا تصحيح مرجعي محدود، وليس حكمًا شاملًا على كل الصيغ.</small>':''}`);};}
else if(m==='grammar'){body.innerHTML=`<h2>قاعدة واحدة… وتطبيق واضح</h2><div class="prompt de">${esc(t.sentence)}</div><p class="writing-note">${t.explain}</p><h3 class="de">${esc(t.quiz)}</h3><div class="options">${t.options.map(v=>`<button class="option">${esc(v)}</button>`).join('')}</div>`;document.querySelectorAll('.option').forEach(e=>e.onclick=()=>{const ok=e.textContent===t.correct;document.querySelectorAll('.option').forEach(o=>{o.disabled=true;if(o.textContent===t.correct)o.classList.add('correct');else if(o===e)o.classList.add('wrong');});finishAttempt(ok,'قواعد',e.textContent);});}
else if(m==='speak'){body.innerHTML=`<h2>اسمع السؤال… وخد وقتك في الرد</h2><div class="prompt de">${esc(t.question)} <button class="text-link" data-say="${esc(t.question)}">◖)) اسمع</button></div><div class="actions"><button class="secondary" data-say="${esc(t.answer)}">◖)) اسمع رد طبيعي</button><button class="secondary" id="reveal-answer">اعرض الرد والترجمة</button></div><div id="model-answer" hidden><p class="de">${esc(t.answer)}</p><p class="subtle">${t.translation}</p></div><p class="writing-note">ابدأ بكلمة، ثم جملة قصيرة، ثم الرد كاملًا. ركّز على وضوح الحروف وإيقاع الجملة؛ مش السرعة.</p><div class="actions"><button class="primary" id="record">● سجّل ردك (حتى ٤٥ ثانية)</button><button class="secondary" id="stop" disabled>■ إيقاف</button></div><p id="mic-status" class="mic-status" aria-live="polite">التسجيل يبقى على جهازك، ولا يُحفظ بعد ترك التمرين.</p><audio id="playback" controls hidden style="width:100%;margin:15px 0"></audio><p class="subtle">تقييم ذاتي: هل قدرت تجاوب بجملة واضحة؟ لا يوجد تحليل آلي للنطق أو درجة صوتية.</p>`;$('#reveal-answer').onclick=()=>$('#model-answer').hidden=false;$('#record').onclick=startRecording;$('#stop').onclick=()=>stopRecording();$('#exercise-actions').innerHTML='<button class="primary" id="self-good">جاوبت بوضوح ✓</button><button class="secondary" id="self-again">محتاج تدريب تاني</button>';$('#self-good').onclick=()=>finishAttempt(true,'شفوي (تقييم ذاتي)');$('#self-again').onclick=()=>finishAttempt(false,'شفوي (تقييم ذاتي)',t.question);}
if(t.id==='time'){body.insertAdjacentHTML?.('beforeend','<div class="writing-note" style="margin-top:22px"><b>الساعة في أمثلة سريعة</b><div class="de">03:15 → Viertel nach drei<br>07:05 → fünf nach sieben<br>02:30 → halb drei<br>04:50 → zehn vor fünf<br>12:00 → zwölf Uhr<br>05:10 → fünf Uhr zehn</div>ممكن تسأل: <span class="inline-de">Wie spät ist es? / Wie viel Uhr ist es?</span></div>');}
if(t.id==='months'){body.insertAdjacentHTML?.('beforeend','<div class="writing-note" style="margin-top:22px"><b>الشهور بالترتيب</b><div class="de">Januar · Februar · März · April · Mai · Juni · Juli · August · September · Oktober · November · Dezember</div></div>');}
if(t.id==='weather'){body.insertAdjacentHTML?.('beforeend','<div class="writing-note" style="margin-top:22px"><b>الفصول والصفات</b><div class="de">Frühling · Sommer · Herbst · Winter<br>warm ↔ kalt · sonnig · regnerisch</div></div>');}
if(m==='speak'){body.insertAdjacentHTML?.('beforeend','<div class="writing-note"><b>دقيقة للنطق</b>في <span class="inline-de">ich</span> يكون ch صوتًا خفيفًا قريبًا من احتكاك الهواء، وليس شينًا ثقيلة. في <span class="inline-de">spielen</span> تبدأ sp بصوت «شپ». اسمع النموذج وكرر مقطعًا قصيرًا، ثم الجملة كاملة.</div>');}
bind();}
function norm(s){return s.normalize('NFC').toLocaleLowerCase('de-DE').replace(/[.,!?;:„“"'’]/g,'').replace(/\s+/g,' ').trim();}
function feedback(ok,html){$('#exercise-feedback').innerHTML=`<div class="feedback ${ok?'':'bad'}">${html}</div>`;}
function finishAttempt(ok,kind,detail='',custom=''){stopMedia();record(topic,ok,kind,detail);feedback(ok,custom||`<b>${ok?'تمام، خطوة للأمام!':'نرجع لها مع بعض.'}</b>${topic.explain}`);$('#exercise-actions').innerHTML=`<button class="primary" id="next-topic">${mode==='daily'&&step<3?'الخطوة التالية ←':'تدريب آخر ←'}</button><button class="secondary" id="retry">جرّب تاني</button>`;$('#next-topic').onclick=()=>{if(mode==='daily'&&step<3){step++;render();}else{const list=filtered();topic=list[(list.findIndex(t=>t.id===topic.id)+1)%list.length];step=0;render();}};$('#retry').onclick=()=>render();}
function quizIntro(){return `<div class="panel"><span class="badge">${state.level} · ٥ أسئلة في كل مرة</span><h2>دقائق قليلة، ونعرف نراجع إيه.</h2><p class="subtle">أسئلة عشوائية بترتيب اختيارات مختلف. النتيجة والشرح والأخطاء هيتحفظوا في سجلّك.</p><div class="actions"><button class="primary" data-quiz="level">ابدأ اختبار ${state.level} ←</button><button class="secondary" data-quiz="all">اختبار مختلط A1–B2</button><button class="secondary" data-quiz="weak">اختبر نقاط الضعف</button></div></div>`;}
function quizLanding(){$('#app').innerHTML=`<div class="view-head"><h1>اختبار صغير، فهم أكبر</h1><p>مش امتحان نهائي؛ فرصة تعرف الخطوة اللي محتاج ترجع لها.</p></div><div class="toolbar">${levelTabs()}</div>${quizIntro()}`;}
function shuffle(a){const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]];}return b;}
function startQuiz(kind){stopMedia();let pool=kind==='all'?TOPICS:kind==='weak'?TOPICS.filter(t=>getItem(t.id).status===2):kind==='weekly'?TOPICS.filter(t=>getItem(t.id).last):filtered();if(!pool.length){showModal('<h3>لسه مفيش موضوعات هنا</h3><p>ابدأ بتدريب أو اختبار مستوى أولًا؛ الأخطاء هتظهر تلقائيًا في مراجعة نقاط الضعف.</p>');return;}quiz={kind,list:shuffle(pool).slice(0,5),index:0,score:0,answered:false,log:[]};topic=null;view='quiz';render();}
function renderQuiz(){const q=quiz;if(q.index>=q.list.length){if(q.kind==='weekly'&&!q.finished){state.lastWeekly=Date.now();save();q.finished=true;}$('#app').innerHTML=`<div class="exercise"><div class="panel"><span class="badge">اكتمل الاختبار · ${q.list.length} أسئلة</span><h2>كل محاولة بتعلّمك حاجة</h2><div class="score">${q.score}<span style="font-size:25px;color:#93a382"> / ${q.list.length}</span></div><p class="subtle">${q.score===q.list.length?'ممتاز! حافظ على المراجعة عشان المعلومة تثبت.':'راجع النقاط دي، وارجع اختبر نفسك تاني.'}</p>${q.log.map(r=>`<div class="record"><span>${r.ok?'✓':'↶'}</span><div><b>${r.t.title}</b><div class="de">${esc(r.t.correct)}</div><small>${r.t.explain}</small></div></div>`).join('')}<div class="actions"><button class="primary" data-quiz="${q.kind}">اختبار عشوائي جديد ↶</button><button class="secondary" onclick="go('progress')">عرض سجلّي</button></div></div></div>`;return;}
const t=q.list[q.index];$('#app').innerHTML=`<div class="exercise"><div class="panel"><div class="section-title"><span class="badge">${t.level} · ${t.title}</span><span class="subtle">السؤال ${q.index+1} من ${q.list.length}</span></div><div class="progress-line"><span style="width:${q.index/q.list.length*100}%"></span></div><h2 class="de">${esc(t.quiz)}</h2><p class="subtle">اختار الإجابة الصحيحة.</p><div class="options">${shuffle(t.options).map((v,i)=>`<button class="option" data-answer="${esc(v)}"><span style="color:#99a58e;margin-right:18px">${String.fromCharCode(65+i)}</span>${esc(v)}</button>`).join('')}</div><div id="quiz-feedback" aria-live="polite"></div><div class="actions" id="quiz-actions"></div></div></div>`;document.querySelectorAll('[data-answer]').forEach(e=>e.onclick=()=>{if(q.answered)return;q.answered=true;const ok=e.dataset.answer===t.correct;if(ok)q.score++;q.log.push({t,ok});record(t,ok,'اختبار MCQ',e.dataset.answer);document.querySelectorAll('[data-answer]').forEach(o=>{o.disabled=true;if(o.dataset.answer===t.correct)o.classList.add('correct');else if(o===e)o.classList.add('wrong');});$('#quiz-feedback').innerHTML=`<div class="feedback ${ok?'':'bad'}"><b>${ok?'إجابة صحيحة ✓':'الإجابة الصحيحة: '+esc(t.correct)}</b>${t.explain}</div>`;$('#quiz-actions').innerHTML='<button class="primary" id="next-q">التالي ←</button>';$('#next-q').onclick=()=>{q.index++;q.answered=false;render();};});}
function review(){const d=due();$('#app').innerHTML=`<div class="view-head"><h1>اللي بنراجعه… بيفضل معانا</h1><p>الخطأ يرجع للمراجعة فورًا، والإجابة الصحيحة بعد يوم، والمتقن بعد أسبوع.</p></div><div class="toolbar"><select id="status-filter" aria-label="مرحلة التعلّم"><option value="due">مستحق للمراجعة (${d.length})</option>${statusLabels.map((s,i)=>`<option value="${i}">${s}</option>`).join('')}<option value="all">كل الموضوعات</option></select><button class="secondary" data-quiz="weak">اختبار نقاط الضعف</button><button class="secondary" data-quiz="weekly">مراجعتي الأسبوعية</button></div><p class="subtle">آخر مراجعة أسبوعية: ${state.lastWeekly?new Date(state.lastWeekly).toLocaleDateString('ar-EG'):'لسه مبدأتش'} · الأسبوعية تراجع عينة عشوائية من الموضوعات التي تدربت عليها.</p><div id="review-list"></div>`;const fill=()=>{const s=$('#status-filter').value;const list=s==='due'?d:s==='all'?TOPICS:TOPICS.filter(t=>getItem(t.id).status===+s);$('#review-list').innerHTML=list.length?`<div class="lesson-grid">${list.map(t=>`<div class="panel"><span class="badge">${t.level} · ${t.title}</span><h3 class="de">${esc(t.word)}</h3><span class="subtle">${t.meaning} · ${getItem(t.id).bad} أخطاء</span><select class="status-select" data-status="${t.id}" aria-label="مرحلة ${t.title}">${statusLabels.map((l,i)=>`<option value="${i}" ${getItem(t.id).status===i?'selected':''}>${l}</option>`).join('')}</select><button class="secondary" data-topic="${t.id}" data-kind="words">مراجعة الموضوع ←</button></div>`).join('')}</div>`:'<div class="panel empty">✧<br>مفيش موضوعات في المرحلة دي حاليًا.<br>ابدأ تدريب، أو اختار مرحلة تانية من القائمة.</div>';bind();};$('#status-filter').onchange=fill;fill();}
function progress(){const errors=state.records.filter(r=>!r.correct);$('#app').innerHTML=`<div class="view-head"><h1>تقدّمك مش مجرد درجات</h1><p>كل محاولة محفوظة عشان تعرف اتحسّنت في إيه، وترجع للي محتاج تدريب.</p></div><div class="stats">${statusLabels.map((l,i)=>`<div class="stat"><span class="stat-icon">${['○','↗','↶','✓'][i]}</span><div><small>${l}</small><strong>${TOPICS.filter(t=>getItem(t.id).status===i).length}</strong><span class="unit">موضوع</span></div></div>`).join('')}</div><div class="toolbar"><button class="secondary" id="export">↓ نسخة احتياطية للتقدّم</button><button class="secondary" id="import">↑ استعادة نسخة</button><input id="import-file" type="file" accept="application/json" hidden><span class="subtle">مراحل الإتقان تلقائية بعد ٣ نجاحات وبفارق نجاحين عن الأخطاء؛ أو تحددها بنفسك في المراجعة.</span></div><div class="bottom-grid"><div class="panel"><h3>سجل المحاولات والدرجات</h3>${state.records.length?state.records.slice(0,25).map(r=>`<div class="record"><span class="badge">${r.correct?'١ / ١':'٠ / ١'}</span><div><b>${TOPICS.find(t=>t.id===r.id)?.title||'موضوع'}</b><small class="subtle" style="display:block">${esc(r.kind)} · ${new Date(r.time).toLocaleDateString('ar-EG')}</small></div></div>`).join(''):'<div class="empty">سجلك مستني أول خطوة منك.</div>'}</div><div class="panel"><h3>أخطائي ونقاط محتاجة إعادة</h3>${errors.length?errors.slice(0,15).map(r=>{const t=TOPICS.find(t=>t.id===r.id);return `<div class="record"><div><b>${t.title}</b><div class="de subtle">${esc(r.detail||t.word)}</div><small>${t.explain}</small></div><button class="text-link" data-topic="${t.id}" data-kind="grammar">أراجع ←</button></div>`;}).join(''):'<div class="empty">هنا هتظهر أخطاؤك بشرحها وتدريب ترجع له.</div>'}</div></div>`;$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,...state},null,2)],{type:'application/json'});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download='schritt-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),5000);};$('#import').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error();const v=JSON.parse(await f.text());if(v.version!==1||!Array.isArray(v.records)||!Array.isArray(v.visits)||!v.items||!['A1','A2','B1','B2'].includes(v.level))throw Error();const ids=new Set(TOPICS.map(t=>t.id));if(v.records.some(r=>!ids.has(r.id)||typeof r.correct!=='boolean'||!Number.isFinite(r.time)||typeof r.kind!=='string')||Object.entries(v.items).some(([id,i])=>!ids.has(id)||![0,1,2,3].includes(i.status)||!Number.isFinite(i.ok)||!Number.isFinite(i.bad)))throw Error();showModal('<h3>استعادة التقدّم</h3><p>النسخة فيها '+v.records.length+' محاولة. استعادتها هتستبدل السجل الحالي على المتصفح.</p><button class="primary" id="confirm-import">استبدال السجل بهذه النسخة</button>');$('#confirm-import').onclick=()=>{state={level:v.level,records:v.records.slice(0,1200),items:v.items,visits:v.visits.filter(x=>typeof x==='string'),lastWeekly:v.lastWeekly||null};save();$('#modal').hidden=true;render();};}catch{showModal('<h3>تعذّر قراءة النسخة</h3><p>اختار نسخة JSON سليمة صدّرتها من خطوة.</p>');}};}
function showModal(html){$('#modal').innerHTML=`<div class="panel">${html}<div class="actions"><button class="secondary" id="close-modal">إغلاق</button></div></div>`;$('#modal').hidden=false;$('#close-modal').onclick=()=>$('#modal').hidden=true;}
$('#modal').onclick=e=>{if(e.target===$('#modal'))$('#modal').hidden=true;};document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#modal').hidden=true;});
function say(text){if(!('speechSynthesis'in window)){showModal('<h3>الصوت غير متاح</h3><p>هذا المتصفح لا يدعم قراءة النص. يمكنك قراءة النموذج والتسجيل للمقارنة الذاتية.</p>');return;}speechSynthesis.cancel();const voices=speechSynthesis.getVoices();const voice=voices.find(v=>v.lang.startsWith('de')&&v.localService);if(!voice){showModal('<h3>أضف صوتًا ألمانيًا على جهازك</h3><p>لا يوجد صوت ألماني محلي متاح حاليًا. جرّب تثبيت حزمة الصوت الألماني من إعدادات جهازك ثم إعادة فتح الصفحة. نستخدم الأصوات المحلية فقط للمحافظة على خصوصية التدريب.</p>');return;}const u=new SpeechSynthesisUtterance(text);u.voice=voice;u.lang='de-DE';u.rate=.82;speechSynthesis.speak(u);}
async function startRecording(){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){$('#mic-status').textContent='التسجيل غير مدعوم في هذا المتصفح. اتدرّب بصوتك وقيم نفسك، أو جرّب متصفحًا أحدث.';return;}const target=topic;try{stream=await navigator.mediaDevices.getUserMedia({audio:true});if(topic!==target||currentMode()!=='speak'){stream.getTracks().forEach(t=>t.stop());stream=null;return;}const chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=()=>{if(topic===target&&$('#playback')){if(audioURL)URL.revokeObjectURL(audioURL);audioURL=URL.createObjectURL(new Blob(chunks,{type:recorder.mimeType||'audio/webm'}));$('#playback').src=audioURL;$('#playback').hidden=false;$('#mic-status').textContent='اسمع تسجيلك وقارنه بالنموذج. التقييم ذاتي، بدون تحليل آلي.';if($('#record'))$('#record').disabled=false;if($('#stop'))$('#stop').disabled=true;}if(stream){stream.getTracks().forEach(t=>t.stop());stream=null;}};recorder.start();$('#record').disabled=true;$('#stop').disabled=false;$('#mic-status').textContent='● جاري التسجيل… خُد نفس واتكلّم بهدوء.';countdown=setTimeout(stopRecording,45000);}catch{$('#mic-status')&&($('#mic-status').textContent='لم يُسمح بالميكروفون أو إنه غير متاح. اسمح به من إعدادات الموقع، أو اتدرّب بدون تسجيل.');if(stream){stream.getTracks().forEach(t=>t.stop());stream=null;}}}
function stopRecording(){clearTimeout(countdown);if(recorder&&recorder.state==='recording')recorder.stop();}
function stopMedia(){stopRecording();if(stream){stream.getTracks().forEach(t=>t.stop());stream=null;}if(audioURL){URL.revokeObjectURL(audioURL);audioURL=null;}if('speechSynthesis'in window)speechSynthesis.cancel();}
window.addEventListener('pagehide',stopMedia);window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(navs.some(n=>n[0]===v)&&view!==v)go(v);});const initial=location.hash.slice(1);if(navs.some(n=>n[0]===initial))view=initial;render();
